#[inline]
pub fn drb_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, DRB_IDENTIFIER, false)
}

#[inline]
pub fn drb_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, DRB_IDENTIFIER, true)
}

#[inline]
pub fn finish_drb_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<DRB<'a>>
) {
    fbb.finish(root, Some(DRB_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_drb_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<DRB<'a>>
) {
    fbb.finish_size_prefixed(root, Some(DRB_IDENTIFIER));
}
